// Q33_AnyaTimerCallback (PrisonOfIce): per-frame anim driver for the rescued Anya NPC walking to/within Harrogath.
// Neutral->Walk; while Walk in Harrogath counts ticks until bAnyaCanRun (then Run), elsewhere waits for bAnyaReachable;
// Run->GetHit. Re-arms itself each frame (+0x19). Animates Anya's escort back to town.
void __fastcall Q33_AnyaTimerCallback(D2QuestDataStrc * pQuestData, D2UnitStrc * pUnit) {
    eD2MonsterAnimMode eCurrentMode;
    D2RoomStrc* pUnitRoom;
    eD2LevelId eLevelId;
    D2QuestDataA5Q3Strc* pA5Q3Data;
    eD2MonsterAnimMode nAnimMode;
    if (!pUnit) {
      eCurrentMode = Death;
    } else {
      eCurrentMode = pUnit->eAnimMode.ePlayerMode;
    }

    switch (eCurrentMode) {
      case eD2MonsterAnimMode_ns::Neutral:
        {
          nAnimMode = Walk;
          break;
        }
      case Walk:
        {
          pA5Q3Data = pQuestData->pQuestSpecificData.pA5Q3;
          pUnitRoom = D2Common::Units::UNITS_GetRoom(pUnit);
          eLevelId = D2Common::DUNGEON::Dungeon::DRLGROOM_GetLevelIdFromRoom(pUnitRoom);
          if (eLevelId == LEVEL_Harrogath) {
            pA5Q3Data->nWalkTickCount++;
            if (pA5Q3Data->nWalkTickCount > 5) {
              pA5Q3Data->bAnyaCanRun = 1;
            }
            if (!pA5Q3Data->bAnyaCanRun) {
              goto rearm_timer;
            }

            nAnimMode = eD2MonsterAnimMode_ns::GetHit;
          } else {
            if (!pA5Q3Data->bAnyaReachable) {
              goto rearm_timer;
            }

            nAnimMode = eD2MonsterAnimMode_ns::GetHit;
          }

          break;
        }
      default:
        {
          goto rearm_timer;
        }
      case eD2MonsterAnimMode_ns::GetHit:
        {
          nAnimMode = eD2MonsterAnimMode_ns::Attack1;
          break;
        }
    }

    D2Common::Units::SetupUpdateFlag(pUnit, nAnimMode);
    rearm_timer:
    GAME::Event::SetEvent(pQuestData->pGame, pUnit, 7, pQuestData->pGame->dwGameFrame + 0x19, 0, 0);
}

// Q33_GetAnyaCoordinates (PrisonOfIce): returns the stored portal coords if active, portal spawned and Anya not yet
// running. Used to locate the rescue portal.
uint32_t __thiscall Q33_GetAnyaCoordinates(void * pThis, int32_t * pOutCoords) {
    D2QuestDataStrc* pQuestData = GetQuestDataByQuestNoInternal((::SGAMEDATA*)pThis, QUESTINT_PrisonOfIce);
    if (pQuestData && pQuestData->bIsNotIntroduction != '\0') {
      D2QuestDataA5Q3Strc* pA5Q3Data;
      pA5Q3Data = pQuestData->pQuestSpecificData.pA5Q3;
      if (pA5Q3Data->bPortalSpawned && !pA5Q3Data->bAnyaCanRun) {
        *pOutCoords = pA5Q3Data->nPortalSpawnX;
        pOutCoords[1] = pA5Q3Data->nPortalSpawnY;
        return 1;
      }
    }

    return 0;
}

// Q33_SpawnPortalNearAnya (PrisonOfIce): creates the town-portal OBJECT (classId 0xbd) at stored coords in a nearby
// valid room (nudging coords +3 if none found), once. Records portal GUID. The portal Anya uses to return to Harrogath.
BOOL __fastcall Q33_SpawnPortalNearAnya(::SGAMEDATA * pGame, D2UnitStrc * pUnit) {
    D2UnitStrc* pPortalUnit;
    D2QuestDataA5Q3Strc* pQuestSpecificA1Q4b;
    int nPortalX;
    D2QuestDataStrc* pQuestData = GetQuestDataByQuestNoInternal(pGame, QUESTINT_PrisonOfIce);
    if (!pQuestData) {
      return 0;
    }

    D2QuestDataA5Q3Strc* pDVar2 = pQuestData->pQuestSpecificData.pA5Q3;
    if (pDVar2->bAnyaPositionStored) {
      return 1;
    }
    if (!pDVar2->nAnyaState) {
      return 0;
    }

    int nPortalY = pDVar2->sAnyaPosition.y;
    D2RoomStrc* pNearbyRoom = D2Common::Units::UNITS_GetRoom(pUnit);
    pNearbyRoom = D2Client::UNIT::Player::DRLGROOM_FindBetterNearbyRoom(pNearbyRoom, pDVar2->sAnyaPosition.x, nPortalY);
    if (!pNearbyRoom) {
      pDVar2->sAnyaPosition.x += 3;
      pDVar2->sAnyaPosition.y += 3;
    } else {
      pPortalUnit = UNIT::SUnit::CreateUnit(UNIT_OBJECT, 0xbd, pDVar2->sAnyaPosition.x, pDVar2->sAnyaPosition.y, pGame, pNearbyRoom, 1, 1, nullptr);
      if (pPortalUnit) {
        pDVar2->bAnyaPositionStored = 1;
        pDVar2->nAnyaPortalGUID = pPortalUnit->nUnitGUID;
        return 1;
      }
    }

    return 0;
}

// Q33_GetAnyaOrPortalCoords (PrisonOfIce): if Anya-state set, outputs the stored Anya position (or live coords if not
// yet stored) into pPoint. Returns 1 on success.
BOOL __fastcall Q33_GetAnyaOrPortalCoords(::SGAMEDATA * pGame, D2UnitStrc * pUnit, POINT * pPoint) {
    D2QuestDataStrc* pQuestData = GetQuestDataByQuestNoInternal(pGame, QUESTINT_PrisonOfIce);
    if (!pQuestData) {
      return 0;
    }

    D2QuestDataA5Q3Strc* pA5Q3Data = pQuestData->pQuestSpecificData.pA5Q3;
    if (!pA5Q3Data->nAnyaState) {
      return 0;
    }
    if (!pA5Q3Data->bAnyaPositionStored) {
      D2Common::Units::GetCoords(pUnit, pPoint);
      return 1;
    }

    pPoint->x = pA5Q3Data->sAnyaPosition.x;
    pPoint->y = pA5Q3Data->sAnyaPosition.y;
    return 1;
}

// Q33_StoreAnyaPosition (PrisonOfIce): captures the rescued-Anya unit's current coords into pA5Q3->sAnyaPosition and
// sets the position-valid flag.
BOOL __fastcall Q33_StoreAnyaPosition(::SGAMEDATA * pGame, D2UnitStrc * pUnit) {
    D2QuestDataStrc* pQuestData = GetQuestDataByQuestNoInternal(pGame, QUESTINT_PrisonOfIce);
    if (!pQuestData) {
      return 0;
    }

    D2QuestDataA5Q3Strc* pA5Q3Data = pQuestData->pQuestSpecificData.pA5Q3;
    D2Common::Units::GetCoords(pUnit, &pA5Q3Data->sAnyaPosition);
    pA5Q3Data->bAnyaPositionValid = 1;
    return 1;
}

